        return self.left.leaves() + self.right.leaves()
    def eval(self, sensors: dict) -> str:
        if self.is_leaf: return self.action
        val = sensors.get(self.condition, 0)
        if val < self.threshold: return self.left.eval(sensors)
        return self.right.eval(sensors)

# ===== block: brain =====
SIZE = 16
FLAT = SIZE * SIZE * SIZE
class AgentBrainMatrixFlat:
    def __init__(self, seed: int):
        self.flat = [0.0] * FLAT
        self.seedFromGenome(seed)
    def seedFromGenome(self, seed: int):
        x = seed & 0xFFFFFFFF
        for i in range(FLAT):
            x = (1664525 * x + 1013904223) & 0xFFFFFFFF
            self.flat[i] = (x / 4294967296.0) * 2 - 1
    def countGateActive(self, thresh: float = 10) -> int:
        return sum(1 for v in self.flat if abs(v) > thresh/100.0 * 2)
    def sense(self, need, health, food, stimulus, pheromone, enemy):
        self.flat[0] = need / 100.0
        self.flat[1] = health / 100.0
        self.flat[2] = food
        self.flat[3] = stimulus
        self.flat[4] = pheromone / 150.0
        self.flat[5] = 1.0 if enemy else 0.0
    def adapt(self):
        nxt = self.flat[:]
        for z in range(SIZE):
            for y in range(SIZE):
                for x in range(SIZE):
                    idx = z*SIZE*SIZE + y*SIZE + x
                    s = 0.0; c = 0
                    for dz in (-1,0,1):
                        for dy in (-1,0,1):
                            for dx in (-1,0,1):
                                nz, ny, nx = z+dz, y+dy, x+dx
                                if 0 <= nz < SIZE and 0 <= ny < SIZE and 0 <= nx < SIZE:
                                    s += self.flat[nz*SIZE*SIZE + ny*SIZE + nx]
                                    c += 1
                    nxt[idx] = s/c * 0.985 + (random.random()-0.5)*0.02
        self.flat = nxt

# ===== MISSING PIECES the artifact never defines (stubs inferred from usage) =====
class Rule:
    def __init__(self, cond, thresh, action, priority):
        self.cond=cond; self.threshold=thresh; self.action=action; self.priority=priority
    def matches(self, sensors):
        return sensors.get(self.cond, 0) < self.threshold
class Task:
    def __init__(self, type='SCAN', path='.', priority=70, user_present=True):
        self.type=type; self.path=path; self.priority=priority; self.user_present=user_present
def mutate(g):
    return GenomeNode(0, max_depth=4)  # artifact has no mutation operator; placeholder

# ===== block: environment (patched: helpers the artifact calls but never defines) =====
class Environment:
    def __init__(self, w=100, h=100, lineages=4):
        self.w, self.h = w, h
        self.lineages = lineages
        self.pheromone = [[[0.0]*w for _ in range(h)] for _ in range(lineages)]
        self.spatial_hash = {}
    def depositPheromone(self, x, y, lineage, amount):
        self.pheromone[lineage][y % self.h][x % self.w] += amount
    def pheromone_at(self, x, y, lineage):
        return self.pheromone[lineage][y % self.h][x % self.w]
    def findStrongestPheromone(self, x, y, radius, lineage):
        best = 0; bestPos = (x,y)
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                v = self.pheromone[lineage][(y+dy)%self.h][(x+dx)%self.w]
                if v > best:
                    best = v; bestPos = (x+dx, y+dy)
        return {'best': best, 'pos': bestPos}
    def evaporate(self, rate=0.985):
        for l in range(self.lineages):
            for y in range(self.h):
                for yy in range(self.w):
                    self.pheromone[l][y][yy] *= rate
    def save(self, path=None):
        pass
    def load(self, path=None):
        pass
    # --- helpers referenced but NEVER defined in the artifact ---
    def food_near(self, x, y): return random.random() < 0.05
    def food_distance(self, x, y): return random.randint(0, 5)
    def consumeFood(self, x, y): pass
    def nearestFood(self, x, y): return (random.randint(0,99), random.randint(0,99))
    def enemies_near(self, x, y): return []
    def nearestEnemy(self, x, y): return None

# ===== block: routing =====
def route(task, agent, env, generation: int):
    urgency = task.priority
    need = 100 - agent.energy
    sensors = {
        'ENERGY_BELOW': need,
        'HEALTH_BELOW': 100 - agent.health,
        'FOOD_PRESENT': 1 if env.food_near(agent.x, agent.y) else 0,
        'STIMULUS_PRESENT': 1 if task.user_present else 0,
        'AGE_AT_LEAST': agent.age,
        'PHEROMONE_STRONG': env.pheromone_at(agent.x, agent.y, agent.lineage),
        'ENEMY_NEARBY': len(env.enemies_near(agent.x, agent.y)),
        'need': need, 'health': agent.health,
        'food': 1, 'stimulus': 1 if task.user_present else 0,
        'pheromone': env.pheromone_at(agent.x, agent.y, agent.lineage),
        'enemy': env.enemies_near(agent.x, agent.y)
    }
    thinking_trace = []
    for depth in range(4):
        agent.brain.sense(sensors['need'], sensors['health'], sensors['food'],
                          sensors['stimulus'], sensors['pheromone'], sensors['enemy'])
        gateActive = agent.brain.countGateActive(10)
        thinking_trace.append(gateActive)
        action = None
        if gateActive > 10 and sensors['STIMULUS_PRESENT']:
            action = 'SEEK'
        else:
            for rule in sorted(agent.rules, key=lambda r: r.priority):
                if rule.matches(sensors):
                    action = rule.action
                    break
        if action is None:
            action = 'IDLE'
        if depth < 3:
            agent.brain.adapt()
    if action == 'SEEK':
        strongest = env.findStrongestPheromone(agent.x, agent.y, 3, agent.lineage)
        follow = strongest['best'] > 10 and random.random() < 0.35
        target = strongest['pos'] if follow else env.nearestFood(agent.x, agent.y)
        dx = 1 if target[0] > agent.x else -1 if target[0] < agent.x else 0
        dy = 1 if target[1] > agent.y else -1 if target[1] < agent.y else 0
        agent.x += dx; agent.y += dy
        env.depositPheromone(agent.x, agent.y, agent.lineage, 6)
        return {'act': 'SEEK_MOVED' if not follow else 'SEEK_PHEROMONE', 'trace': thinking_trace}
    if action == 'EAT' and env.food_distance(agent.x, agent.y) <= 2:
        env.consumeFood(agent.x, agent.y)
        agent.energy = min(100, agent.energy + 12)
        env.depositPheromone(agent.x, agent.y, agent.lineage, 120)
        return {'act': 'EAT', 'trace': thinking_trace}
    if action == 'FIGHT' and sensors['ENEMY_NEARBY'] and agent.energy > 70:
        foe = env.nearestEnemy(agent.x, agent.y)
        if agent.fitness() > foe.fitness():
            agent.energy += 25; foe.health -= 35
            env.depositPheromone(agent.x, agent.y, agent.lineage, 80)
            return {'act': 'FIGHT_WON', 'trace': thinking_trace}
        else:
            agent.health -= 35
            return {'act': 'FIGHT_LOST', 'trace': thinking_trace}
    return {'act': action, 'trace': thinking_trace}

# ===== block: genesis =====
class DigitalLife:
    def __init__(self, x, y, lineage, genome: GenomeNode, brain_seed: int):
        self.x, self.y = x, y
        self.lineage = lineage
        self.genome = genome
        self.brain = AgentBrainMatrixFlat(brain_seed)
        self.energy = 100; self.health = 100
        self.age = 0; self.offspring = 0
        self.rules = [
            Rule('ENERGY_BELOW', 60, 'SEEK', 0),
            Rule('HEALTH_BELOW', 30, 'IDLE', 1),
            Rule('FOOD_PRESENT', 1, 'EAT', 2),
            Rule('STIMULUS_PRESENT', 1, 'SEEK', 3),
            Rule('AGE_AT_LEAST', 20, 'REPRODUCE', 4),
        ]
    def fitness(self) -> int:
        return self.age*2 + self.energy + self.health + self.offspring*20
    def tick(self, task, env, gen):
        res = route(task, self, env, gen)
        self.age += 1
        self.energy = max(0, self.energy - 1)
        return res

class GenesisPermanentAgent:
    def __init__(self, spawn=20):
        self.env = Environment()
        self.env.load()
        self.lineage_counts = {0:5,1:5,2:5,3:5}
        self.subagents = []
        self.memory_path = "/_genesis/memory/"
        self.spawn_n = spawn
        self.boot()
    def boot(self):
        self.env.load()
        n = self.spawn_n // 4
        for lin in range(4):
            for _ in range(n):
                g = GenomeNode(0, max_depth=4)
                self.subagents.append(DigitalLife(random.randint(0,99), random.randint(0,99),
                                                  lin, g, random.randint(0, 2**32)))
    def think_and_route(self, task):
        self.subagents.sort(key=lambda a: a.fitness(), reverse=True)
        results = []
        for agent in self.subagents:
            r = agent.tick(task, self.env, generation=0)
            results.append((agent, r))
        self.env.evaporate(0.985)
        self.cull_if_needed()
        self.env.save()
        return results
    def cull_if_needed(self, MAX=150):
        if len(self.subagents) <= MAX: return
        self.subagents.sort(key=lambda a: a.fitness())
        victims = self.subagents[:len(self.subagents)-MAX]
        for v in victims: self.subagents.remove(v)
        counts = {0:0,1:0,2:0,3:0}
        for a in self.subagents: counts[a.lineage]+=1
        self.lineage_counts = counts
    def save_memory(self): self.env.save()


if __name__ == "__main__":
    import time
    random.seed(7)
    print("=== BOOT ===")
    t0=time.time(); G = GenesisPermanentAgent(spawn=20); print(f"boot {time.time()-t0:.2f}s, pop={len(G.subagents)}")
    print("gate-active on a fresh brain (thresh 10):", G.subagents[0].brain.countGateActive(10), "of 4096")
    print("gate-active at thresh 50:", G.subagents[0].brain.countGateActive(50))
    print()
    print("=== ACTION DISTRIBUTION over 200 tasks ===")
