    dur=time.time()-t0
    print("actions:", dict(acts))
    print(f"200 tasks x {len(G.subagents)} agents in {dur:.2f}s  ({dur/200*1000:.0f} ms/task)")
    print("thinking_trace (task 0, first 5 agents):", traces[:5])
    print("distinct trace patterns:", len(set(traces)), "of", len(traces))
    print("avg fitness start -> end:", round(fits[0],1), "->", round(fits[-1],1))
    print("max fitness any agent:", max(a.fitness() for a in G.subagents))
    print("nodes avg:", round(statistics.mean(a.genome.nodes() for a in G.subagents),2))
    print("pop:", len(G.subagents), "lineage:", G.lineage_counts)
    print("offspring total:", sum(a.offspring for a in G.subagents))
    print("pheromone max deposit present:", max(max(max(r) for r in l) for l in G.env.pheromone))
    print("pheromone nonzero cells:", sum(1 for l in G.env.pheromone for r in l for v in r if v>0))
