{"content":"#!/usr/bin/env python3
"""
GENESIS — DRY-RUN KEEP LIST BUILDER
Reads a v2 duplicate_report.json and decides, per duplicate group, WHICH copy
survives and which are removable. Writes lists only. Never moves or deletes.

Two scenarios are computed, because "one copy total" and "one copy per
taxonomy branch" are different answers and only you can choose:

  SCENARIO A  one copy total          -> maximal reclaim
  SCENARIO B  one copy per branch     -> preserves BY_TOPIC / BY_TYPE structure,
                                         collapses only true re-copies

Safety invariant enforced + verified: for EVERY path marked removable, at least
one path with the identical sha256 survives. If that cannot be shown, the file
is moved to `review` instead of `removable`.

Outputs (into --out):
  keep_list_A.csv / keep_list_B.csv   category,mb,removable_path,keeper_path,sha256
  removable_paths_A.txt / _B.txt      plain list, one path per line
  summary.json                        counts + MB per category and scenario
  review.csv                          cases needing a human look
"""

import json
import os
import sys
import argparse
import csv
from collections import defaultdict, Counter
from pathlib import Path

# Order of preference for the copy that SURVIVES (first match wins).
# Canonical zones first, then semantic organisation, then type, then source.
BRANCH_PREF = ["CANONICAL", "INDEX", "CATALOG", "BY_TOPIC", "BY_TYPE",
               "BY_SOURCE", "BY_DATE"]

# Agent re-copy markers seen in the corpus.
AGENT_SUFFIXES = ["__NORTHSTAR", "__JAVA_MEMORY", "__OPENCLAW", "__HERMES",
                  "__AGENT", "__COPY", "__DUP"]

NESTED_MARKERS = [" copy", "_copy", " (1)", " (2)", "- Copy"]


def top_branch(rel):
    parts = rel.replace("/", "\\").split("\\")
    return parts[0] if len(parts) > 1 else "(root)"


def branch_rank(rel):
    b = top_branch(rel).upper()
    for i, pref in enumerate(BRANCH_PREF):
        if b.startswith(pref):
            return i
    return len(BRANCH_PREF) + 1        # unknown branch: keep preference lowest


def has_nested_copy(rel):
    """Detect a directory segment repeated or copy-marked (whole-subtree re-copy)."""
    parts = [p.lower() for p in rel.replace("/", "\\").split("\\")[:-1]]
    for i in range(1, len(parts)):
        if parts[i] == parts[i - 1]:
            return True
    joined = " ".join(parts)
    return any(m.lower() in joined for m in NESTED_MARKERS)


def has_agent_suffix(name):
    stem = os.path.splitext(name)[0]
    return any(s in stem for s in AGENT_SUFFIXES)


def strip_agent_suffix(name):
    stem, ext = os.path.splitext(name)
    for s in AGENT_SUFFIXES:
        stem = stem.split(s)[0]
    return (stem.strip() + ext).lower()


def pick_keeper(group):
    """Deterministic: preference order, then fewer agent markers, then shallower,
    then shorter, then alphabetical. Returns (keeper, sorted_rest)."""
    files = group["files"]

    def key(f):
        rel = f["rel"]
        return (
            branch_rank(rel),
            1 if has_nested_copy(rel) else 0,
            1 if has_agent_suffix(f["name"]) else 0,
            len(rel.replace("/", "\\").split("\\")),
            len(rel),
            rel.lower(),
        )

    ordered = sorted(files, key=key)
    return ordered[0], ordered[1:]


def classify(keeper, other):
    """Why is `other` removable relative to the keeper?"""
    kb, ob = top_branch(keeper["rel"]), top_branch(other["rel"])
    if has_nested_copy(other["rel"]) and not has_nested_copy(keeper["rel"]):
        return "nested_tree_copy"
    if has_agent_suffix(other["name"]) and not has_agent_suffix(keeper["name"]):
        return "agent_artifact_copy"
    if (has_agent_suffix(other["name"]) and has_agent_suffix(keeper["name"])
            and strip_agent_suffix(other["name"]) == strip_agent_suffix(keeper["name"])):
        return "agent_variant_copy"
    if ob != kb:
        return "taxonomy_duplicate"
    if os.path.dirname(other["rel"]) == os.path.dirname(keeper["rel"]):
        return "same_folder_duplicate"
    return "same_branch_duplicate"


def build(dup_json, out_dir, root_hint=None):
    dup = json.load(open(dup_json, encoding="utf-8"))
    groups = dup["exact_verified"]
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)

    rows_A, rows_B, review = [], [], []
    by_cat_A = defaultdict(lambda: {"files": 0, "mb": 0.0})
    by_cat_B = defaultdict(lambda: {"files": 0, "mb": 0.0})

    total_mb = 0.0
    groups_with_agent = 0
    groups_multi_branch = 0

    for gi, g in enumerate(groups):
        sha = g["sha256"]
        cnt = g["count"]
        size_mb = g["total_size_mb"] / cnt if cnt else 0.0

        keeper, rest = pick_keeper(g)

        # ---- scenario A: keep exactly one copy total
        for other in rest:
            cat = classify(keeper, other)
            rows_A.append({
                "category": cat, "mb": round(size_mb, 4),
                "removable_path": other["path"], "keeper_path": keeper["path"],
                "sha256": sha[:16], "copies_in_group": cnt,
            })
            by_cat_A[cat]["files"] += 1
            by_cat_A[cat]["mb"] += size_mb
        total_mb += size_mb * (cnt - 1)

        # ---- scenario B: keep one copy PER top-level branch
        per_branch = defaultdict(list)
        for f in g["files"]:
