{"content":""""fraymus.invariants — the transferable core, as executable checks.

This module is the abstraction of the Fraymus / Fraynix / OPEG family reduced to
the four things that were actually sound:

    I1  grounded derivation      S0 -> S3 -> S4 -> CONVERGED, no DIRECT_INFERENCE
    I2  sanitization gate        R_san = sigma(R_raw): strip env, keep counters+hash
    I3  receipts                 nothing enters the record without evidence
    I5  content addressing       one seal binds every domain, checkable by anyone

Everything else in that family (the phi^75 integer seal, ProtocolZero's halt,
the EP4 matrix, the MoE loss) was either false or self-contradictory and is
deliberately NOT included.

The seal is a SHA-256 over a sorted manifest of domain digests. It changes when
content changes. It cannot be wrong by 12.
"""

from __future__ import annotations

import hashlib
import json
import time
from dataclasses import dataclass, field, asdict
from enum import Enum
from typing import Any, Callable, Iterable


# ---------------------------------------------------------------- I1: states

class State(str, Enum):
    S0_IDLE = "S0_IDLE"
    S1_PARSE = "S1_PARSE"
    S2_VERIFY_SEAL = "S2_VERIFY_SEAL"
    S3_REASON = "S3_REASON"
    S4_GROUNDED_DERIVATION = "S4_GROUNDED_DERIVATION"
    S_CONVERGED = "S_CONVERGED"


LEGAL = {
    State.S0_IDLE: {State.S1_PARSE},
    State.S1_PARSE: {State.S2_VERIFY_SEAL},
    State.S2_VERIFY_SEAL: {State.S3_REASON},
    State.S3_REASON: {State.S4_GROUNDED_DERIVATION},          # <- only way forward
    State.S4_GROUNDED_DERIVATION: {State.S_CONVERGED},
    State.S_CONVERGED: {State.S0_IDLE},
}


class DirectInference(Exception):
    """Raised on any attempt to reach a conclusion without derivation (S3 -> S_CONVERGED)."""


@dataclass
class Derivation:
    """A conclusion is only legal with its derivation attached."""
    claim: str
    derived_from: list[str]                 # receipt ids
    method: str
    steps: list[str] = field(default_factory=list)

    def __post_init__(self):
        if not self.derived_from:
            raise DirectInference(
                f"claim {self.claim!r} has no supporting receipts -> DIRECT_INFERENCE")
        if not self.method:
            raise DirectInference(f"claim {self.claim!r} has no method -> DIRECT_INFERENCE")


class Machine:
    """The S0..S_CONVERGED walk. Enforces I1."""

    def __init__(self):
        self.state = State.S0_IDLE
        self.trace: list[tuple[str, str]] = []

    def go(self, to: State) -> "Machine":
        if to not in LEGAL[self.state]:
            raise DirectInference(f"illegal transition {self.state.value} -> {to.value}")
        self.trace.append((self.state.value, to.value))
        self.state = to
        return self

    def converge(self, derivation: Derivation) -> Derivation:
        """The only sanctioned path to a conclusion. Requires S4 + a Derivation."""
        if self.state is not State.S4_GROUNDED_DERIVATION:
            raise DirectInference(
                f"cannot converge from {self.state.value}; must pass S4_GROUNDED_DERIVATION")
        self.go(State.S_CONVERGED)
        return derivation


# ---------------------------------------------------------------- I2: the gate

# keys dropped entirely: anything naming a path, user, host, pid, env
_STRIP_EXACT = {
    "path", "env", "environ", "cwd", "argv", "pid", "ppid", "host", "hostname",
    "user", "username", "uid", "gid", "home", "tmpdir", "sys_path",
}
# keys kept as-is: verifiable facts
_COUNTER_KEYS = {
    "count", "n", "total", "hits", "misses", "bytes", "size", "lines", "ops",
    "duration", "ms", "us", "ns", "elapsed", "iterations",
}
# any key containing these is hashed, not copied
_HASH_KEYS = ("hash", "digest", "sha", "merkle", "root", "checksum", "signature")


def sanitize(raw: dict, _depth: int = 0) -> dict:
    """R_san = sigma(R_raw).

    Strips environment and pointers. Preserves counters and hashes.
    Hashes anything that looks like opaque content rather than passing it through.
    """
    if _depth > 12:
        return {"_truncated": True}
    out: dict[str, Any] = {}
    for k, v in raw.items():
        kl = k.lower()
        if kl in _STRIP_EXACT or any(kl.startswith(p) for p in ("path_", "env_", "os_")):
            continue
        if isinstance(v, dict):
            out[k] = sanitize(v, _depth + 1)
        elif isinstance(v, (list, tuple)):
            out[k] = [sanitize(x, _depth + 1) if isinstance(x, dict) else _scalar(x)
                      for x in v][:1000]
        elif any(h in kl for h in _HASH_KEYS) and isinstance(v, str):
            out[k] = v if _looks_like_hex(v) else _sha(v)   # keep real hashes
        elif kl in _COUNTER_KEYS and isinstance(v, (int, float, bool)):
            out[k] = v                                    # keep real counters
        else:
            out[k] = _scalar(v)
    return out


def _scalar(v):
    if isinstance(v, (int, float, bool)) or v is None:
        return v
    if isinstance(v, str):
        return v if len(v) <= 200 else {"_sha256": _sha(v), "_len": len(v)}
    return {"_repr": type(v).__name__}


def _looks_like_hex(s: str) -> bool:
    return len(s) >= 16 and all(c in "0123456789abcdefABCDEF" for c in s)


def _sha(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8", "replace")).hexdigest()


# ---------------------------------------------------------------- I3: receipts

@dataclass
class Receipt:
    """Nothing enters the record without one of these."""
    id: str
    domain: str
    ok: bool
    metrics: dict
    ts: float = field(default_factory=time.time)

    @staticmethod
    def make(domain: str, ok: bool, metrics: dict) -> "Receipt":
        r = Receipt(id="", domain=domain, ok=ok, metrics=sanitize(metrics))
        body = json.dumps({"d": r.domain, "o": r.ok, "m": r.metrics, "t": r.ts},
                          sort_keys=True)
        r.id = hashlib.sha256(body.encode()).hexdigest()[:32]
        return r


class Journal:
    """Append-only receipt log. Refuses ungrounded entries."""

    def __init__(self):
        self._rows: list[Receipt] = []

    def record(self, domain: str, ok: bool, metrics: dict) -> Receipt:
        r = Receipt.make(domain, ok, metrics)
        self._rows.append(r)
        return r

    def ids(self) -> list[str]:
        return [r.id for r in self._rows]

    def verify(self, rid: str) -> bool:
        for r in self._rows:
            if r.id == rid:
                body = json.dumps({"d": r.domain, "o": r.ok, "m": r.metrics, "t": r.ts},
                                  sort_keys=True)
                return hashlib.sha256(body.encode()).hexdigest()[:32] == rid
        return False


# ---------------------------------------------------------------- I5: the seal

class Seal:
    """One root over all domains. A hash, not a numeric identity claim."""

    def __init__(self, version: str = "1.0"):
        self.version = version
        self.domains: dict[str, str] = {}

    def bind(self, name: str, digest: str) -> "Seal":
        self.domains[name] = digest
        return self

    def bind_receipt(self, r: Receipt) -> "Seal":
        return self.bind(r.domain, r.id)

    def root(self) -> str:
        body = json.dumps(
            {"v": self.version, "d": dict(sorted(self.domains.items()))},
            sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(body.encode()).hexdigest()

    def manifest(self) -> dict:
        return {"version": self.version, "root": self.root(),
                "domains": dict(sorted(self.domains.items()))}

    def verify(self, claimed_root: str) -> bool:
        return self.root() == claimed_root


# ---------------------------------------------------------------- domain cells

class Cell:
    """An execution cell. No shared mutable state with other cells."""

    name: str = "cell"

    def run(self, **kw) -> dict:
        raise NotImplementedError


class HashCell(Cell):
    name = "hash"

    def run(self, payload: bytes = b"", **kw) -> dict:
        return {"count": 1, "bytes": len(payload),
                "sha256": hashlib.sha256(payload).hexdigest(),
                "path": "/should/be/stripped", "env": {"SHOULD": "GO"}}


class CounterCell(Cell):
    name = "counter"

    def run(self, items: Iterable = (), **kw) -> dict:
        items = list(items)
        return {"count": len(items), "total": len(items),
                "distinct": len(set(map(str, items))), "cwd": "/strip/me"}


class DNACell(Cell):
    """bytes -> bases. 1 byte = 4 bases, 2 bits each. Honest 4x, no compression lies."""
    name = "dna"
    MAP = "ACGT"

    @staticmethod
    def encode(data: bytes) -> str:
        out = []
        for b in data:
            out += [DNACell.MAP[(b >> 6) & 3], DNACell.MAP[(b >> 4) & 3],
                    DNACell.MAP[(b >> 2) & 3], DNACell.MAP[b & 3]]
        return "".join(out)

    @staticmethod
    def decode(s: str) -> bytes:
        idx = {c: i for i, c in enumerate(DNACell.MAP)}
        bits = "".join(format(idx[c], "02b") for c in s)
        return bytes(int(bits[i:i + 8], 2) for i in range(0, len(bits) - 7, 8))

    def run(self, payload: bytes = b"", **kw) -> dict:
        enc = self.encode(payload)
        dec = self.decode(enc)
        bases = len(enc)
        words = bases // 32
        return {
            "bytes_in": len(payload),
            "bases": bases,
            "words": words,
            "expansion": round(bases / max(1, len(payload)), 3),
            "roundtrip_ok": dec == payload,
            "bits_per_base": 2,
        }


class VSStubCell(Cell):
    """bytes -> Unicode variation selectors. Range is 240, NOT 256."""
    name = "vs"
    LO, HI = 0xE0100, 0xE01EF

    @staticmethod
    def slots() -> int:
        return VSStubCell.HI - VSStubCell.LO + 1

    def run(self, payload: bytes = b"", **kw) -> dict:
        ok = all(0 <= b < self.slots() for b in payload)
        return {"bytes_in": len(payload), "slots": self.slots(),
                "all_encodable": ok, "limit": self.slots()}


# ---------------------------------------------------------------- orchestrator

class Grid:
    """OPEG reduced: bind cells under one seal, gate their output, require derivation."""

    def __init__(self, seal_version: str = "1.0"):
        self.journal = Journal()
        self.seal = Seal(seal_version)
        self.machine = Machine()

    def execute(self, cells: list[Cell], **kw) -> dict:
        self.machine.go(State.S1_PARSE).go(State.S2_VERIFY_SEAL)
        results = {}
        for c in cells:
            raw = c.run(**kw)
            r = self.journal.record(c.name, True, raw)     # I2 applied inside
            self.seal.bind_receipt(r)
            results[c.name] = r
        self.machine.go(State.S3_REASON)
        return results

    def seal_check(self) -> dict:
        m = self.seal.manifest()
        m["self_verified"] = self.seal.verify(m["root"])
        return m

    def conclude(self, claim: str, method: str, steps: list[str]) -> Receipt:
        d = Derivation(claim=claim, derived_from=self.journal.ids(),
                       method=method, steps=steps)
        self.machine.go(State.S4_GROUNDED_DERIVATION)
        self.machine.converge(d)
        return self.journal.record("conclusion", True,
                                   {"claim": claim, "method": method, "steps": steps})


def _demo():
    g = Grid()
    payload = b"FRAYMUS ABSTRACTION"
    res = g.execute([HashCell(), CounterCell(), DNACell(), VSStubCell()],
                    payload=payload)
    print("--- receipts (R_san) ---")
    for name, r in res.items():
        print(f"  {name:9s} id={r.id[:12]}  {json.dumps(r.metrics, sort_keys=True)[:110]}")
    print("\n--- seal ---")
    print(json.dumps(g.seal_check(), indent=2)[:400])

    print("\n--- I1: DIRECT_INFERENCE is refused ---")
    for bad in (
        lambda: Machine().converge(Derivation("no receipts", [], "none")),
        lambda: Machine().go(State.S_CONVERGED),
        lambda: Derivation("claim", ["r1"], ""),
    ):
        try:
            bad()
            print("  !! allowed (BUG)")
        except DirectInference as e:
            print("  refused:", str(e)[:78])

    print("\n--- grounded conclusion ---")
    rc = g.conclude("pipeline round-trips losslessly",
                    "DNACell.encode/decode equality",
                    ["encode", "decode", "compare"])
    print("  conclusion receipt:", rc.id[:16])
    print("  journal verifies:", g.journal.verify(rc.id))

    print("\n--- sanity numbers ---")
    print("  VS slots:", VSStubCell.slots(), "(240, not 256)")
    print("  64*64 =", 64 * 64, "-> bases", 64 * 64 * 4, "-> words", 64 * 64 * 4 // 32)


if __name__ == "__main__":
    _demo()
