def _get_with_js(self, url: str) -> str:
    """Fallback for JS-heavy sites using Playwright if installed."""
    try:
        from playwright.sync_api import sync_playwright
    except ImportError:
        raise ImportError("JS rendering requires: pip install playwright && playwright install")

    with sync_playwright() as p:
        browser = p.chromium.launch(headless=self.headless)
        page = browser.new_page(user_agent=self.session.headers["User-Agent"])
        page.goto(url, timeout=self.timeout * 1000)
        page.wait_for_load_state("networkidle")
        html = page.content()
        browser.close()
        return html

def _parse_extract(self, soup: BeautifulSoup, extract: Dict[str, Dict], base_url: str) -> Dict[str, Any]:
    """Extract structured data via selector map."""
    data = {}
    for key, cfg in extract.items():
        selector = cfg.get("selector")
        attr = cfg.get("attr", "text")  # text, html, href, src, or any attr
        all_matches = cfg.get("all", False)
        join_base = cfg.get("join_base", False)  # for links
        regex = cfg.get("regex")

        if not selector:
            continue

        elements = soup.select(selector)
        if not elements:
            data[key] = [] if all_matches else None
            continue

        def get_val(el):
            if attr == "text":
                val = el.get_text(strip=True)
            elif attr == "html":
                val = el.decode_contents()
            else:
                val = el.get(attr, "")
                if join_base and val:
                    val = urljoin(base_url, val)
            if regex and val:
                m = re.search(regex, val)
                val = m.group(1) if m and m.groups() else (m.group(0) if m else val)
            return val

        if all_matches:
            data[key] = [get_val(el) for el in elements]
        else:
            data[key] = get_val(elements[0])
    return data

def scrape_url(
    self,
    url: str,
    selector: Optional[str] = None,
    extract: Optional[Dict[str, Dict]] = None,
    get_links: bool = True,
    use_js: bool = False,
) -> ScrapedResult:
    """
    Main method.

    Args:
        url: Target URL
        selector: Simple CSS selector to return text list for
        extract: Dict like {"title": {"selector": "h1", "attr": "text"}, "url": {"selector": "a", "attr": "href", "all": True, "join_base": True}}
        get_links: Collect all <a> hrefs
        use_js: Force JS rendering
    """
    try:
        if use_js:
            html = self._get_with_js(url)
            status = 200
        else:
            resp = self._get(url)
            status = resp.status_code
            html = resp.text if status == 200 else ""

        if not html:
            return ScrapedResult(url=url, status_code=status, error=f"Empty response, status {status}")

        soup = BeautifulSoup(html, "lxml")

        # auto metadata
        metadata = {
            "title": soup.title.string.strip() if soup.title and soup.title.string else "",
            "description": "",
            "canonical": "",
        }
        desc_tag = soup.find("meta", attrs={"name": "description"}) or soup.find("meta", attrs={"property": "og:description"})
        if desc_tag:
            metadata["description"] = desc_tag.get("content", "")
        canon = soup.find("link", rel="canonical")
        if canon:
            metadata["canonical"] = canon.get("href", "")

        data = {}
        if extract:
            data = self._parse_extract(soup, extract, url)
        elif selector:
            els = soup.select(selector)
            data["results"] = [e.get_text(strip=True) for e in els]

        links = []
        if get_links:
            for a in soup.find_all("a", href=True):
href = a["href"]
                full = urljoin(url, href)
                if full.startswith("http"):
                    links.append(full)
            links = list(dict.fromkeys(links))  # dedupe preserve order

        return ScrapedResult(
            url=url,
            status_code=status,
            html=html,
            soup=soup,
            data=data,
            links=links,
            metadata=metadata,
        )

    except Exception as e:
        return ScrapedResult(url=url, status_code=0, error=str(e))

def crawl(
    self,
    start_url: str,
    max_pages: int = 20,
    same_domain: bool = True,
    selector: Optional[str] = None,
    extract: Optional[Dict[str, Dict]] = None,
) -> List[ScrapedResult]:
    """Breadth-first crawl."""
    visited = set()
    queue = [start_url]
    results = []
    domain = urlparse(start_url).netloc

    while queue and len(results) < max_pages:
        url = queue.pop(0)
        if url in visited:
            continue
        visited.add(url)

        res = self.scrape_url(url, selector=selector, extract=extract, get_links=True)
        results.append(res)

        if res.links and len(results) < max_pages:
            for link in res.links:
                if link not in visited:
                    if same_domain and urlparse(link).netloc != domain:
                        continue
                    if link not in queue:
                        queue.append(link)
    return results
