class WebScraper:
    """Agent-native web scraper: robots.txt, rate limiting, structured extraction."""

    DEFAULT_HEADERS = {
        "User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                       "(KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36"),
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "en-US,en;q=0.9",
        "Accept-Encoding": "gzip, deflate",
        "Connection": "keep-alive",
        "Upgrade-Insecure-Requests": "1",
    }

    def __init__(self, headless: bool = True, respect_robots: bool = True,
                 delay: float = 1.0, timeout: int = 15, max_retries: int = 2,
                 proxy: Optional[str] = None,
                 headers: Optional[Dict[str, str]] = None):
        self.respect_robots = respect_robots
        self.delay = delay
        self.timeout = timeout
        self.max_retries = max_retries
        self.headless = headless
        self.session = requests.Session()
        self.session.headers.update(headers or self.DEFAULT_HEADERS)

        # BUGFIX (original): proxies were set via session.proxies.update on a
        # dict keyed "http"/"https" — that works, but the original also never
        # warned that a generic proxy relay is a MITM by construction. Kept the
        # capability, documented the hazard (matches blocked-page-recovery).
        if proxy:
            self.session.proxies.update({"http": proxy, "https": proxy})

        self._robots_cache: Dict[str, urllib.robotparser.RobotFileParser] = {}
        self._last_request = 0.0          # BUGFIX: track real rate limit

    # ---------------------------------------------------------------- core
    def _can_fetch(self, url: str) -> bool:
        if not self.respect_robots:
            return True
        try:
            parsed = urlparse(url)
            base = f"{parsed.scheme}://{parsed.netloc}"
            if base not in self._robots_cache:
                rp = urllib.robotparser.RobotFileParser()
                rp.set_url(urljoin(base, "/robots.txt"))
                try:
                    rp.read()
                except Exception:
                    return True          # fail open, as original intended
                self._robots_cache[base] = rp
            ua = self.session.headers.get("User-Agent", "*")
            return self._robots_cache[base].can_fetch(ua, url)
        except Exception:
            return True

    def _throttle(self, attempt: int):
        """BUGFIX (original): the original slept delay+random on retries but
        random*delay on first attempt, so the FIRST request was unthrottled and
        bursts were possible. This enforces a real minimum gap between requests."""
        if attempt > 0:
            time.sleep(self.delay + random.uniform(0, 1))
            return
        gap = time.time() - self._last_request
        if gap < self.delay:
            time.sleep(self.delay - gap + random.uniform(0, 0.25))

    def _get(self, url: str) -> requests.Response:
        if not self._can_fetch(url):
            raise PermissionError(f"Blocked by robots.txt: {url}")

        last_exc = None
        for attempt in range(self.max_retries + 1):
            self._throttle(attempt)
            try:
                resp = self.session.get(url, timeout=self.timeout)
                self._last_request = time.time()

                if resp.status_code == 429:                # rate limited
                    wait = 2 ** attempt * 2
                    time.sleep(wait)
                    last_exc = requests.RequestException(f"429 rate limited (waited {wait}s)")
                    continue
                return resp
            except requests.RequestException as e:
                last_exc = e
                if attempt == self.max_retries:
                    break
        # BUGFIX (original): the original fell through the loop silently when the
        # final attempt raised, then raised a bare RuntimeError losing the cause.
        raise last_exc or RuntimeError("Max retries exceeded")

    def _get_with_js(self, url: str) -> str:
        """JS rendering fallback. Playwright is optional; degrades cleanly."""
        try:
            from playwright.sync_api import sync_playwright
        except ImportError:
            raise ImportError(
                "JS rendering requires: pip install playwright && playwright install\n"
                "  (not installed on this host — use browser_exec instead for JS pages)"
            )
        with sync_playwright() as p:
            browser = p.chromium.launch(headless=self.headless)
            page = browser.new_page(user_agent=self.session.headers["User-Agent"])
            page.goto(url, timeout=self.timeout * 1000)
            page.wait_for_load_state("networkidle")
            html = page.content()
            browser.close()
            return html

