    def _parse_extract(self, soup: BeautifulSoup, extract: Dict[str, Dict],
                       base_url: str) -> Dict[str, Any]:
        """Selector map extraction.

        cfg keys: selector (CSS), attr (text|html|href|src|<any>|data-*),
                  all (bool), join_base (bool), regex (str)
        """
        data: Dict[str, Any] = {}
        for key, cfg in extract.items():
            selector = cfg.get("selector")
            if not selector:
                continue
            attr = cfg.get("attr", "text")
            all_matches = cfg.get("all", False)
            join_base = cfg.get("join_base", False)
            rx = cfg.get("regex")

            try:
                elements = soup.select(selector)
            except Exception as e:
                data[key] = {"error": f"bad selector: {e}"}
                continue

            if not elements:
                data[key] = [] if all_matches else None
                continue

            def get_val(el) -> Any:
                if attr == "text":
                    val: Any = el.get_text(strip=True)
                elif attr == "html":
                    val = el.decode_contents()
                else:
                    val = el.get(attr, "")
                    if join_base and val:
                        val = urljoin(base_url, val)
                if rx and isinstance(val, str) and val:
                    m = re.search(rx, val)
                    if m:
                        val = m.group(1) if m.groups() else m.group(0)
                return val

            data[key] = [get_val(el) for el in elements] if all_matches else get_val(elements[0])
        return data

    # ---------------------------------------------------------------- scrape
    def scrape_url(self, url: str, selector: Optional[str] = None,
                   extract: Optional[Dict[str, Dict]] = None,
                   get_links: bool = True, use_js: bool = False) -> ScrapedResult:
        try:
            if use_js:
                html = self._get_with_js(url)
                status = 200
            else:
                resp = self._get(url)
                status = resp.status_code
                html = resp.text if status == 200 else ""

            if not html:
                return ScrapedResult(url=url, status_code=status,
                                     error=f"Empty response, status {status}")

            soup = BeautifulSoup(html, "lxml")

            metadata = {
                "title": soup.title.string.strip() if soup.title and soup.title.string else "",
                "description": "",
                "canonical": "",
            }
            desc = (soup.find("meta", attrs={"name": "description"})
                    or soup.find("meta", attrs={"property": "og:description"}))
            if desc:
                metadata["description"] = desc.get("content", "")
            canon = soup.find("link", rel="canonical")
            if canon:
                metadata["canonical"] = canon.get("href", "")

            data: Dict[str, Any] = {}
            if extract:
                data = self._parse_extract(soup, extract, url)
            elif selector:
                els = soup.select(selector)
                data["results"] = [e.get_text(strip=True) for e in els]

            links: List[str] = []
            if get_links:
                for a in soup.find_all("a", href=True):
                    full = urljoin(url, a["href"])
                    if full.startswith("http"):
                        links.append(full)
                links = list(dict.fromkeys(links))     # dedupe, preserve order

            return ScrapedResult(url=url, status_code=status, html=html, soup=soup,
                                 data=data, links=links, metadata=metadata)
        except Exception as e:
            return ScrapedResult(url=url, status_code=0,
                                 error=f"{type(e).__name__}: {e}")

    # ---------------------------------------------------------------- crawl
    def crawl(self, start_url: str, max_pages: int = 20, same_domain: bool = True,
              selector: Optional[str] = None,
              extract: Optional[Dict[str, Dict]] = None) -> List[ScrapedResult]:
        visited, queue, results = set(), [start_url], []
        domain = urlparse(start_url).netloc
        while queue and len(results) < max_pages:
            url = queue.pop(0)
            if url in visited:
                continue
            visited.add(url)
            res = self.scrape_url(url, selector=selector, extract=extract, get_links=True)
            results.append(res)
            if res.links and len(results) < max_pages:
                for link in res.links:
                    if link not in visited and link not in queue:
                        if same_domain and urlparse(link).netloc != domain:
                            continue
                        queue.append(link)
        return results


# ---------------------------------------------------------------- shortcut
_default_scraper: Optional[WebScraper] = None


def scrape(url: str, selector: Optional[str] = None,
           extract: Optional[Dict] = None, use_js: bool = False,
           **kwargs) -> ScrapedResult:
    """One-liner: scrape(url, selector="h1") or scrape(url, extract={...})"""
    global _default_scraper
    if _default_scraper is None:
        _default_scraper = WebScraper(**kwargs)
    return _default_scraper.scrape_url(url, selector=selector, extract=extract, use_js=use_js)


