{"content":"// audit_baseline.mjs — audit of the Fraymus WASM DNA format.
//
// Answers AGENT_BRIEF §6.4: "fraymus.baseline was switched from DJB2 to SHA-256;
// the verifier needs a full audit to confirm round-trip integrity."
//
// Runs the REAL engine from src/lib/fraymus.js, not a reimplementation.
// Doubles as the regression test for the verifyWasm fix.

import { createHash, webcrypto } from 'crypto';
import { pathToFileURL } from 'url';

if (!globalThis.crypto) globalThis.crypto = webcrypto;
if (!globalThis.btoa) globalThis.btoa = (s) => Buffer.from(s, 'binary').toString('base64');
if (!globalThis.atob) globalThis.atob = (s) => Buffer.from(s, 'base64').toString('binary');

const fraymus = await import(
  pathToFileURL('C:/Users/eyeka/fraymus-wasm-forge/src/lib/fraymus.js').href
);
const { transmute, verifyWasm, decodeWasmFile } = fraymus;

const sha256 = (b) => createHash('sha256').update(Buffer.from(b)).digest('hex');

function djb2(bytes) {
  let h = 5381;
  for (const b of bytes) h = ((h * 33) ^ b) >>> 0;
  return (h >>> 0).toString(16).padStart(8, '0');
}

const asFile = (name, bytes) => ({
  name,
  arrayBuffer: async () => bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength),
});

const decode = async (u8) => decodeWasmFile(asFile('x.wasm', u8));

function findSection(u, wantName) {
  let i = 8;
  while (i < u.length) {
    const secId = u[i++];
    let len = 0, shift = 0;
    for (;;) { const b = u[i++]; len |= (b & 0x7f) << shift; shift += 7; if (!(b & 0x80)) break; }
    const bodyStart = i, secEnd = bodyStart + len;
    if (secId === 0x00) {
      let nl = 0, ns = 0, ni = bodyStart;
      for (;;) { const b = u[ni++]; nl |= (b & 0x7f) << ns; ns += 7; if (!(b & 0x80)) break; }
      const name = new TextDecoder().decode(u.subarray(ni, ni + nl));
      if (name === wantName) return { name, payloadStart: ni + nl, payloadEnd: secEnd };
    }
    i = secEnd;
  }
  return null;
}

const R = [];
const rec = (label, ok, detail) => {
  R.push(ok);
  console.log(`  [${ok ? 'PASS' : 'FAIL'}] ${label.padEnd(54)} ${detail}`);
};

console.log('\n' + '='.repeat(80));
console.log('  FRAYMUS WASM DNA AUDIT — AGENT_BRIEF §6.4');
console.log('='.repeat(80));

// ------------------------------------------------------------------ corpus
const corpus = [
  ['plain text',    new TextEncoder().encode('Fraymus Living Engine\nφ = 1.618033988749895\n')],
  ['phi multibyte', new TextEncoder().encode('φ'.repeat(64) + '⁷⁵')],
  ['nulls + high',  new Uint8Array([0x00, 0xff, 0x00, 0x7f, 0x80, 0xc3, 0x28, 0x00])],
  ['embedded wasm', new Uint8Array([0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, 0xde, 0xad])],
  ['empty',         new Uint8Array(0)],
  ['1 byte',        new Uint8Array([0x42])],
];

console.log('\n### 1. baseline algorithm identity (SHA-256 vs DJB2)');
let allSha = true, sawDjb2 = false;
for (const [name, bytes] of corpus) {
  const r = await transmute(asFile(`${name}.bin`, bytes));
  const declared = r.ledger.sha256;
  const isSha = declared === sha256(bytes);
  const isD = declared === djb2(bytes);
  if (!isSha) allSha = false;
  if (isD) sawDjb2 = true;
  console.log(`   ${name.padEnd(14)} declared=${String(declared).slice(0, 16)}… sha=${isSha} djb2=${isD}`);
}
rec('ledger.sha256 == real SHA-256, all inputs', allSha, '6/6 including adversarial bytes');
rec('ledger.sha256 never equals DJB2', !sawDjb2, 'DJB2 hex is 8 chars; digest is 64');

// ------------------------------------------------------- round-trip integrity
console.log('\n### 2. round-trip byte equality');
let allRt = true;
for (const [name, bytes] of corpus) {
  const r = await transmute(asFile(`${name}.bin`, bytes));
  const d = await decode(new Uint8Array(r.wasm));
  const same = d.original && Buffer.from(d.original).equals(Buffer.from(bytes));
  if (!same) { allRt = false; console.log(`   ${name}: MISMATCH (${bytes.length} in, ${d.original?.length ?? 0} out)`); }
}
rec('every input round-trips byte-identically', allRt, `${corpus.length}/${corpus.length} exact`);

// --------------------------------------------------------------- structure
console.log('\n### 3. binary structure');
const r1 = await transmute(asFile('t.txt', corpus[0][1]));
const wasm = new Uint8Array(r1.wasm);
const decoded = await decode(wasm);
const EXPECTED = ['fraymus.baseline', 'fraymus.dna', 'fraymus.genesis', 'fraymus.ledger', 'fraymus.data'];
console.log(`   bytes=${wasm.length}  magic=${[...wasm.slice(0, 4)].map(x => x.toString(16).padStart(2, '0')).join(' ')}`);
console.log(`   sections=${JSON.stringify(decoded.sectionNames)}`);
const missing = EXPECTED.filter((n) => !decoded.sectionNames.includes(n));
rec('all 5 custom sections present', missing.length === 0, missing.length ? 'missing: ' + missing : '5/5');
try {
  const mod = new WebAssembly.Module(wasm);
  const exps = WebAssembly.Module.exports(mod);
  rec('compiles as a real WASM module', true, `${exps.length} export(s): ${exps.map(e => e.name).join(', ')}`);
} catch (e) {
  rec('compiles as a real WASM module', false, String(e.message).slice(0, 90));
}

// ------------------------------------------------------------- the real test
console.log('\n### 4. tamper detection (the audit fix regression test)');
const sec = findSection(wasm, 'fraymus.data');
const tampered = new Uint8Array(wasm);
const b64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const tgt = sec.payloadStart + 5;
const origCh = String.fromCharCode(tampered[tgt]);
tampered[tgt] = b64[(b64.indexOf(origCh) + 1) % 64].charCodeAt(0);
console.log(`   flipped byte ${tgt} in fraymus.data: '${origCh}' -> '${String.fromCharCode(tampered[tgt])}'`);

const vT = await verifyWasm(tampered);
const dT = await decode(tampered);
const changed = dT.original && !Buffer.from(dT.original).equals(Buffer.from(decoded.original));
rec('tamper actually changed the payload', changed === true, 'data differs from original');
rec('verifyWasm REJECTS the tampered file', vT.valid === false, vT.valid === false ? 'rejected' : 'still accepted');
rec('baselineMatchesActual is false', vT.baselineMatchesActual === false, String(vT.baselineMatchesActual));
if (vT.actualSha256) {
  console.log(`   baseline  : ${vT.baseline}`);
  console.log(`   recomputed: ${vT.actualSha256}`);
}

// ------------------------------------------------- ledger cross-check
console.log('\n### 5. ledger / baseline cross-check');
const vGood = await verifyWasm(wasm);
rec('untampered file still verifies', vGood.valid === true, `valid=${vGood.valid}`);
rec('ledger sha256 agrees with baseline', vGood.ledgerAgrees === true, String(vGood.ledgerAgrees));

// forge a mismatch: rewrite fraymus.baseline to a different-but-valid-looking hash
const secB = findSection(wasm, 'fraymus.baseline');
const forged = new Uint8Array(wasm);
forged[secB.payloadStart] = '0'.charCodeAt(0) === forged[secB.payloadStart]
  ? '1'.charCodeAt(0) : '0'.charCodeAt(0);
const vF = await verifyWasm(forged);
rec('forged baseline is rejected', vF.valid === false, `valid=${vF.valid}, matchesActual=${vF.baselineMatchesActual}`);

// ----------------------------------------------------------- module exports
console.log('\n### 6. API surface');
console.log(`   exported: ${Object.keys(fraymus).join(', ')}`);
rec('verifyWasm is async after the fix', verifyWasm.constructor.name === 'AsyncFunction',
  verifyWasm.constructor.name);

console.log('\n' + '='.repeat(80));
const pass = R.filter(Boolean).length;
console.log(`  ${pass}/${R.length} checks pass`);
console.log('='.repeat(80) + '\n');
process.exit(pass === R.length ? 0 : 1);
