import { createHash, webcrypto } from 'crypto';
import { pathToFileURL } from 'url';

if (!globalThis.crypto) globalThis.crypto = webcrypto;
if (!globalThis.btoa) globalThis.btoa = (s) => Buffer.from(s, 'binary').toString('base64');
if (!globalThis.atob) globalThis.atob = (s) => Buffer.from(s, 'base64').toString('binary');

const base = 'C:/Users/eyeka/fraymus-wasm-forge/src/lib/';
const { transmute, verifyWasm, decodeWasmFile } = await import(pathToFileURL(base + 'fraymus.js').href);
const { CLASSIC_WASMS, buildClassicWasm } = await import(pathToFileURL(base + 'forge.js').href);
const { buildJar, decodeJar } = await import(pathToFileURL(base + 'jar.js').href);

const sha256 = (b) => createHash('sha256').update(Buffer.from(b)).digest('hex');
const asFile = (name, bytes) => ({
  name,
  arrayBuffer: async () => bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength),
});
const decode = (u8) => decodeWasmFile(asFile('x.wasm', u8));

// ---- generic WASM section walker -------------------------------------------
function walkSections(u) {
  const out = [];
  let i = 8;
  while (i < u.length) {
    const id = u[i++];
    let len = 0, shift = 0;
    for (;;) { const b = u[i++]; len |= (b & 0x7f) << shift; shift += 7; if (!(b & 0x80)) break; }
    const bodyStart = i, end = bodyStart + len;
    if (end > u.length) { out.push({ id, name: null, truncated: true, declared: len, available: u.length - bodyStart }); break; }
    let name = null, payloadStart = bodyStart;
    if (id === 0x00) {
      let nl = 0, ns = 0, ni = bodyStart;
      for (;;) { const b = u[ni++]; nl |= (b & 0x7f) << ns; ns += 7; if (!(b & 0x80)) break; }
      name = new TextDecoder().decode(u.subarray(ni, ni + nl));
      payloadStart = ni + nl;
    }
    out.push({ id, name, payloadStart, payloadEnd: end, size: end - bodyStart });
    i = end;
  }
  return out;
}

