  ['phi multibyte',new TextEncoder().encode('φ'.repeat(64) + '⁷⁵Δ')],
  ['nulls+high',   new Uint8Array([0, 0xff, 0x7f, 0x80, 0xc3, 0x28, 0, 0xfe])],
  ['embedded wasm',new Uint8Array([0, 0x61, 0x73, 0x6d, 1, 0, 0, 0, 0xde, 0xad])],
  ['empty',        new Uint8Array(0)],
  ['1 byte',       new Uint8Array([0x42])],
];
let a1 = true, a2 = true, a3 = true;
for (const [name, bytes] of corpus) {
