    compiles = true;
  } catch (e) { /* compiles stays false */ }
  const v = await verifyWasm(wasm);

  const missing5 = EXPECTED5.filter((n) => !names.includes(n));
  const declaredOk = ledger.sha256 === w.hash;                 // trivially true (copy)
  const declaredIsRealHash = w.hash === sha256(data);          // is it a hash OF the data?
  const hashLen = w.hash.length;

