    classOf(CLASSIC_WASMS[0].hash)}, not a digest of anything`);

function classOf(h) {
  if (/^[0-9a-f]{64}$/.test(h)) return 'a 64-char SHA-256';
  if (/^[0-9a-f]{8}$/.test(h)) return `an 8-char constant`;
  const numeric = /^\d+$/.test(h);
  return numeric ? 'a decimal constant' : 'an 8-char hex constant';
}

