const jarInputs = [
  { name: 'a.txt', bytes: new TextEncoder().encode('alpha φ content') },
  { name: 'b.bin', bytes: new Uint8Array([0, 1, 2, 0xff, 0xfe, 0x00]) },
  { name: 'empty.txt', bytes: new Uint8Array(0) },
];
let c1 = true, c2 = true, c3 = true;
const jar = await buildJar(jarInputs, { compress: true });
const jarU8 = new Uint8Array(jar.bytes ?? jar.buffer ?? jar);
console.log(`   jar entry: ${jar.name ?? '(unnamed)'}  bytes=${jarU8.length}`);
try {
  const dec = await decodeJar(jarU8.buffer ? jarU8 : jarU8.buffer);
  const files = dec.files || [];
  console.log(`   decoded files: ${files.length}`);
  for (const orig of jarInputs) {
    const f = files.find((x) => x.name === orig.name);
    const ok = !!f && Buffer.from(f.bytes).equals(Buffer.from(orig.bytes));
    if (!ok) { c1 = false; console.log(`     ${orig.name}: MISMATCH`); }
