  console.log(`   decodeJar failed: ${String(e.message).slice(0, 120)}`);
}
rec('C1 jar round-trip byte-identical', c1, `${jarInputs.length} inputs incl. empty + binary`);
rec('C2 jar per-file sha256 is a real SHA-256', c2, 'sha256 field verified against recomputation');

