export function transpileCppToJava(code, opts = {}) {
  const className = opts.className || 'Converted';

  // Pre-pass: namespace ns { ... }  ->  flattened with a marker comment.
  // Java has no namespaces; package declarations are the nearest mapping.
  code = code.replace(/\bnamespace\s+(\w+)\s*\{/g, '// namespace $1 -> nested scope flattened');
  code = code.replace(/\bnamespace\s+\w+\s*;?/g, '');

  // Pre-pass: template<typename T>  ->  erased. Java generics are type-erased at
  // runtime, so a <T> method becomes an Object-typed method with a cast site.
  code = code.replace(/template\s*<\s*typename\s+(\w+)\s*>/g,
    '// generic <$1> erased (Java generics are erased at runtime)');
  code = code.replace(/template\s*<\s*class\s+(\w+)\s*>/g,
    '// generic <$1> erased (Java generics are erased at runtime)');

  // Pre-pass: multiple inheritance -> first base extends, rest via comment.
  code = code.replace(
    /\bclass\s+(\w+)\s*:\s*public\s+(\w+)\s*,\s*public\s+(\w+)/g,
    (m, derived, base1, base2) =>
      `class ${derived} extends ${base1} /* also implemented: ${base2} — Java has single inheritance; extract an interface */`);

  // Pre-pass: destructors -> Java finalization hint (no deterministic destructors).
  code = code.replace(/~(\w+)\s*\(\s*\)\s*\{/g,
    'void close() { // C++ destructor ~$1 -> explicit close(); Java has no deterministic destruction');

  const lines = code.split('\n');
  const javaLines = [];
  javaLines.push(`public class ${className} {`);

  let depth = 0;
  for (let line of lines) {
    // Strip Pointers (The dangerous part)
    if (line.includes('*') && !line.includes('import') && !line.includes('//')) {
      line = line.replace(/\*/g, '') + ' // WARN: Pointer stripped';
    }
    // Apply Regex Mappings
    for (const [pat, rep] of CPP_TO_JAVA) {
      line = line.replace(new RegExp(pat, 'g'), rep);
    }
    // Remove public:/private:/protected: access sections
    if (line.includes('public:') || line.includes('private:') || line.includes('protected:')) continue;

    // Do NOT nest a class inside the wrapper: a C++ class declaration becomes a
    // top-level Java class, otherwise you get `class C` inside `public class
    // Converted`, which is not what a caller expects.
    const classDecl = line.match(/^\s*(final\s+)?class\s+(\w+)(\s+extends\s+\w+)?/);
    if (classDecl) {
      if (depth > 0) { javaLines.push('}'); depth--; }
      javaLines.push(line.trim());
      depth++;
      continue;
    }

    javaLines.push(depth > 0 ? '    ' + line.trim() : line);
  }
  while (depth-- > 0) javaLines.push('}');
  return javaLines.join('\n');
