{"content":"// probe_transpiler_real.mjs — run go2java / janus against REAL source files,
// not synthetic snippets. Synthetic corpora test the rules you thought of;
// real files test the ones you didn't.
//
// Usage: node probe_transpiler_real.mjs [--limit N]

import { readFileSync, existsSync } from 'fs';
import { execSync } from 'child_process';
import { pathToFileURL } from 'url';

const base = 'C:/Users/eyeka/fraymus-wasm-forge/src/lib/';
const { transpileGoToJava } = await import(pathToFileURL(base + 'go2java.js').href);
const { transpileCppToJava, transpileJavaToCpp } = await import(pathToFileURL(base + 'janus.js').href);

// ---- corpus -----------------------------------------------------------------
function findFiles(root, exts, skip) {
  const out = [];
  let n = 0;
  const walk = (dir) => {
    let entries;
    try { entries = execSync(`find "${dir}" -maxdepth 6 -type f ${exts.map(e => `-name "*${e}"`).join(' -o ')} 2>/dev/null || true`,
      { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 }); } catch { return; }
    for (const line of entries.split('\n')) {
      const p = line.trim();
      if (!p || skip.some((s) => p.includes(s))) continue;
      try { const sz = readFileSync(p).length; if (sz > 200 && sz < 400000) out.push(p); } catch {}
      if (++n > 4000) return;
    }
  };
  walk(root);
  return out;
}

const SKIP = ['node_modules', '/.git/', '__pycache__', 'site-packages', '/dist/', '/build/'];
const roots = process.argv.slice(2).filter((a) => !a.startsWith('--'));
const limitArg = process.argv.find((a) => a.startsWith('--limit'));
const LIMIT = limitArg ? parseInt(limitArg.split('=')[1] || process.argv[process.argv.indexOf(limitArg) + 1], 10) : 8;

const goFiles = [
  ...findFiles('C:/Users/eyeka/Downloads/java-memory-V1-main-20260918T233421Z-1-001', ['.go'], SKIP),
].slice(0, LIMIT);
const cppFiles = findFiles('C:/Users/eyeka/Downloads', ['.cpp', '.cc'], SKIP).slice(0, LIMIT);
const javaFiles = findFiles('C:/Users/eyeka/Downloads/java-memory-V1-main-20260918T233421Z-1-001', ['.java'], SKIP)
  .sort((a, b) => readFileSync(a).length - readFileSync(b).length)
  .slice(0, LIMIT);

// ---- the check ---------------------------------------------------------------
// A construct "survives" if it appears in the OUTPUT outside comments.
// Any survival means the transpiler silently emitted Go/C++ that will not compile.
function stripComments(s) {
  return s.split('\n').map((l) => l.replace(/\/\/.*$/, '').replace(/\/\*[\s\S]*?\*\//g, '')).join('\n');
}

const GO_LEAKS = [
  [/\bfunc\s+\w+\s*\(/, 'func declaration'],
  [/\bpackage\s+\w+/, 'package clause'],
  [/:=/, 'short var decl'],
  [/\bchan\b/, 'chan type'],
  [/\bdefer\b/, 'defer'],
  [/\bgo\s+\w+\(/, 'goroutine launch'],
  [/\bselect\s*\{/, 'select block'],
  [/\brange\s+/, 'range'],
  [/\bnil\b/, 'nil'],
  [/\biota\b/, 'iota'],
  [/\[\](\w+)\b/, 'Go slice type'],
  [/\btype\s+\w+\s+struct/, 'struct decl'],
  [/\btype\s+\w+\s+interface/, 'interface decl'],
  [/\bif\s+err\s*!=\s*nil/, 'Go error idiom'],
  [/\bfmt\./, 'fmt package'],
];

const CPP_LEAKS = [
  [/\btemplate\s*</, 'template'],
  [/\bnamespace\s+\w+/, 'namespace'],
  [/#include\s*</, '#include'],
  [/\bstd::/, 'std::'],
  [/->/, 'arrow member access'],
  [/~\w+\s*\(\s*\)/, 'destructor'],
  [/\bnew\s+\w+\[/, 'raw array new'],
  [/\bdelete\s*\[\]/, 'delete[]'],
  [/\bauto\b/, 'auto'],
  [/\bconst\b/, 'const qualifier'],
  [/\bvirtual\b/, 'virtual'],
  [/\bpublic:\s*$/, 'access section'],
  [/\bbool\b/, 'bool'],
];

const JAVA_LEAKS = [
  [/\bpublic\s+class\b/, 'public class'],
  [/\bextends\b/, 'extends'],
  [/\bimplements\b/, 'implements'],
  [/\bArrayList\s*</, 'ArrayList'],
  [/\bSystem\.out\./, 'System.out'],
  [/\bString\b/, 'String type'],
  [/\bboolean\b/, 'boolean'],
  [/\bnew\s+\w+\s*\(/, 'new expression'],
];

function checkLeaks(out, rules) {
  const scan = stripComments(out).split('\n').filter((l) => l.trim()).join('\n');
  return rules.filter(([re]) => re.test(scan)).map(([, name]) => name);
}

function run(label, files, fn, rules) {
  console.log('\n' + '='.repeat(86));
  console.log('  ' + label);
  console.log('='.repeat(86));
  if (!files.length) { console.log('  no files found'); return { clean: 0, total: 0 }; }
  let clean = 0;
  for (const f of files) {
    const src = readFileSync(f, 'utf8');
    let out;
    try { out = fn(src).code ?? fn(src); } catch (e) { out = `__ERROR__ ${e.message}`; }
    const isErr = typeof out === 'string' && out.startsWith('__ERROR__');
    const leaks = isErr ? ['THREW'] : checkLeaks(out, rules);
    const short = f.split(/[\\/]/).slice(-1)[0];
    if (!isErr && leaks.length === 0) { clean++; console.log(`  [CLEAN] ${short.padEnd(42)} ${src.length}b -> ${out.length}b`); }
    else console.log(`  [LEAK ] ${short.padEnd(42)} ${isErr ? out.slice(0, 60) : leaks.join(', ')}`);
  }
  console.log(`  -> ${clean}/${files.length} produced output with no leaked source syntax`);
  return { clean, total: files.length };
}

const r1 = run('GO -> JAVA  (real .go files)', goFiles, transpileGoToJava, GO_LEAKS);
const r2 = run('C++ -> JAVA  (real .cpp files)', cppFiles, transpileCppToJava, CPP_LEAKS);
const r3 = run('JAVA -> C++  (real .java files)', javaFiles, transpileJavaToCpp, JAVA_LEAKS);

console.log('\n' + '='.repeat(86));
const c = r1.clean + r2.clean + r3.clean, t = r1.total + r2.total + r3.total;
console.log(`  REAL-FILE TOTAL: ${c}/${t} clean`);
console.log('  (synthetic corpus was 30/30 — this is the number that matters)');
console.log('='.repeat(86) + '\n');
