  const bytes = await buildClassicWasm(spec.type, spec.name, enc.encode(spec.name), { hash: spec.hash, size: spec.size });
  const v = await verifyWasm(bytes);
  rec(`classic ${spec.name}`,
      `bytes=${bytes.length} sha256=${sha(bytes).slice(0,40)}… verifies=${v.valid} catalog=${spec.hash}`);
}

