import { createClientFromRequest } from 'npm:@base44/sdk@0.8.44';
import { secrets } from 'base44:runtime';

// Proxy to a user-owned Ollama instance (OLLAMA_HOST secret).
// Keeps the host private and avoids browser CORS.
export default async function(req) {
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 });

    const host = (secrets.get('OLLAMA_HOST') || '').replace(/\/$/, '');
    if (!host) return Response.json({ error: 'OLLAMA_HOST not configured' }, { status: 500 });

    const body = await req.json().catch(() => ({}));
    const action = body.action || 'chat';

    if (action === 'models') {
      const r = await fetch(`${host}/api/tags`);
      if (!r.ok) {
        const hint = r.status === 403
          ? 'Ollama returned 403 — it is blocking non-localhost requests. On the VPS, restart Ollama with OLLAMA_ORIGINS="*" and OLLAMA_HOST=0.0.0.0:11434, and open port 11434.'
          : `Ollama ${r.status}`;
        return Response.json({ error: hint }, { status: 502 });
      }
      const data = await r.json();
      return Response.json({ models: (data.models || []).map((m) => m.name) });
    }

    // chat
    const model = body.model || 'llama3.2';
    const messages = Array.isArray(body.messages) ? body.messages : [];
    if (!messages.length) return Response.json({ error: 'No messages' }, { status: 400 });

    const r = await fetch(`${host}/api/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model, messages, stream: false })
    });
    if (!r.ok) {
      const txt = await r.text().catch(() => '');
      const hint = r.status === 403
        ? 'Ollama returned 403 — it is blocking non-localhost requests. On the VPS, restart Ollama with OLLAMA_ORIGINS="*" and OLLAMA_HOST=0.0.0.0:11434, and open port 11434.'
        : `Ollama ${r.status}: ${txt.slice(0, 200)}`;
      return Response.json({ error: hint }, { status: 502 });
    }
    const data = await r.json();
    return Response.json({ content: data.message?.content || '', model: data.model });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
}
